```html
<!DOCTYPE html>
<html>
<head>
<style>
/* 欲神幻想风格动画 */
@keyframes roe-pulse-hover {
    0% { box-shadow: 0 0 0 0 rgba(212, 175, 55, 0.4); }
    100% { box-shadow: 0 0 0 10px rgba(212, 175, 55, 0); }
}
@keyframes roe-badge-pop {
    0% { transform: scale(0.5); opacity: 0; }
    70% { transform: scale(1.3); }
    100% { transform: scale(1); opacity: 1; }
}
@keyframes roe-glow-text {
    0% { text-shadow: 0 0 5px rgba(220, 20, 60, 0.5); }
    50% { text-shadow: 0 0 15px rgba(220, 20, 60, 0.9), 0 0 20px rgba(212, 175, 55, 0.6); }
    100% { text-shadow: 0 0 5px rgba(220, 20, 60, 0.5); }
}

/* 全局样式与欲望变量 */
:root {
    --roe-bg-dark: linear-gradient(145deg, #110d14 0%, #1a0f14 50%, #0d090c 100%);
    --roe-gold: #d4af37;
    --roe-gold-dark: #8a7322;
    --roe-red: #8b0000;
    --roe-red-bright: #dc143c;
    --roe-text-light: #f4ecd8;
    --roe-button-bg: rgba(20, 15, 20, 0.85);
    --roe-button-hover: linear-gradient(90deg, rgba(139, 0, 0, 0.4), rgba(212, 175, 55, 0.15));
    --roe-border-soft: rgba(212, 175, 55, 0.3);
    --roe-shadow-gold: 0 0 12px rgba(212, 175, 55, 0.4);
    --roe-shadow-red: 0 0 15px rgba(220, 20, 60, 0.5);
}

/* 容器整体美化 */
.nova-silent-sky {
    display: flex;
    justify-content: center;
    width: 100%;
    padding: 0 8px;
    box-sizing: border-box;
    font-family: 'Times New Roman', 'Georgia', serif;
    margin: 16px auto;
}

.mystic-card-silent {
    flex-grow: 1;
    max-width: 520px;
    background: var(--roe-bg-dark);
    border-radius: 4px;
    padding: 16px;
    box-shadow: 0 10px 30px rgba(0, 0, 0, 0.8), inset 0 0 20px rgba(139, 0, 0, 0.2);
    border: 1px solid var(--roe-gold-dark);
    position: relative;
    overflow: hidden;
}

/* 华丽边角装饰 */
.mystic-card-silent::after {
    content: '';
    position: absolute;
    top: 0; left: 0; right: 0; bottom: 0;
    background:
        linear-gradient(45deg, transparent 48%, var(--roe-gold) 49%, var(--roe-gold) 51%, transparent 52%) 0 0 / 20px 20px no-repeat,
        linear-gradient(-45deg, transparent 48%, var(--roe-gold) 49%, var(--roe-gold) 51%, transparent 52%) 100% 0 / 20px 20px no-repeat;
    pointer-events: none;
    opacity: 0.5;
}

/* 头部标题美化 */
.nova-header {
    padding: 14px 20px;
    cursor: pointer;
    text-align: center;
    font-size: 16px;
    font-weight: bold;
    letter-spacing: 2px;
    color: var(--roe-gold);
    background: linear-gradient(90deg, rgba(20, 15, 20, 0.9), rgba(40, 15, 20, 0.9), rgba(20, 15, 20, 0.9));
    border: 1px solid var(--roe-gold-dark);
    border-radius: 2px;
    transition: all 0.4s cubic-bezier(0.25, 0.8, 0.25, 1);
    position: relative;
    text-transform: uppercase;
    box-shadow: inset 0 0 10px rgba(212, 175, 55, 0.1);
}

.nova-header:hover {
    background: linear-gradient(90deg, rgba(40, 15, 20, 0.9), rgba(80, 20, 30, 0.9), rgba(40, 15, 20, 0.9));
    border-color: var(--roe-gold);
    box-shadow: var(--roe-shadow-gold);
    color: #fff;
    animation: roe-glow-text 2s infinite;
}

/* 折叠内容区域 */
.collapsible-content {
    display: none;
    flex-direction: column;
    gap: 12px;
    margin-top: 16px;
    position: relative;
    z-index: 1;
}

/* 按钮组样式 */
.button-group-silent {
    display: flex;
    flex-direction: column;
    gap: 10px;
}

/* 动态生成的选项按钮美化 */
.action-btn-silent {
    border-radius: 2px;
    padding: 16px 24px;
    padding-right: 45px;
    font-size: 15px;
    font-family: 'Microsoft YaHei', sans-serif;
    line-height: 1.5;
    cursor: pointer;
    text-align: left;
    width: 100%;
    position: relative;
    overflow: hidden;
    transition: all 0.3s ease;
    border: 1px solid rgba(212, 175, 55, 0.2);
    background: var(--roe-button-bg);
    color: var(--roe-text-light);
    border-left: 4px solid var(--roe-gold-dark);
}

.action-btn-silent::before {
    content: '';
    position: absolute;
    top: 0; left: 0; right: 0; bottom: 0;
    background: repeating-linear-gradient(45deg, transparent, transparent 10px, rgba(0,0,0,0.2) 10px, rgba(0,0,0,0.2) 20px);
    opacity: 0.3;
    pointer-events: none;
}

.action-btn-silent:hover {
    background: var(--roe-button-hover);
    border-color: var(--roe-gold);
    border-left: 4px solid var(--roe-red-bright);
    color: #fff;
    transform: translateX(4px);
}

.action-btn-silent.selected {
    background: linear-gradient(135deg, rgba(139, 0, 0, 0.8), rgba(60, 10, 15, 0.9));
    border: 1px solid var(--roe-gold);
    border-left: 6px solid var(--roe-gold);
    color: #fff;
    box-shadow: var(--roe-shadow-red);
    animation: roe-pulse-hover 0.8s ease-out;
}

/* 角标 */
.click-order-badge {
    position: absolute;
    bottom: 10px;
    right: 15px;
