    <div class="trk-wrapper" id="tracker-container">
        <!-- 内容将由JS动态生成 -->
        <div style="text-align:center; padding:10px; color:#7696be;">读取数据中...</div>
    </div>

    <script>
        /* ========== 获取消息内容 ========== */
        function getMessageData() {
            var chatMessages = getChatMessages(getCurrentMessageId());
            if (!chatMessages || chatMessages.length === 0) {
                return null;
            }
            return chatMessages[0].message;
        }

        /* ========== 解析数据 ========== */
        function parseTrackerData(messageText) {
            var result = [];
            var tagMatch = messageText.match(/<tracker>([\s\S]*?)<\/tracker>/);
            if (!tagMatch || !tagMatch[1]) {
                return result;
            }

            var content = tagMatch[1];
            /* 按 "---" 分割多个角色 */
            var roleBlocks = content.split(/---/);

            roleBlocks.forEach(function(block) {
                var blockStr = block.trim();
                if (!blockStr) return;

                var roleData = {};
                /* 提取所有 [字段|值] */
                var regex = /\[([^\|]+)\|([^\]]+)\]/g;
                var match;
                while ((match = regex.exec(blockStr)) !== null) {
                    var key = match[1].trim();
                    var val = match[2].trim();
                    roleData[key] = val;
                }

                if (Object.keys(roleData).length > 0) {
                    result.push(roleData);
                }
            });

            return result;
        }

        /* ========== 绑定折叠事件 ========== */
        function bindToggleEvents() {
            var headers = document.querySelectorAll('.trk-header');
            headers.forEach(function(header) {
                header.onclick = function() {
                    var body = this.nextElementSibling;
                    if (body.style.display === 'block') {
                        body.style.display = 'none';
                        this.classList.remove('is-open');
                    } else {
                        body.style.display = 'block';
                        this.classList.add('is-open');
                    }
                };
            });
        }

        /* ========== 渲染界面 ========== */
        function renderTracker(dataArray) {
            var container = document.getElementById('tracker-container');
            if (dataArray.length === 0) {
                container.innerHTML = '<div style="text-align:center; padding:10px; color:#d87083;">未检测到角色追踪数据</div>';
                return;
            }

            var html = '';
            dataArray.forEach(function(data) {
                var roleName = data['Role'] || '未知角色';
                var location = data['Location'] || '未知地点';
                var action = data['Action'] || '无动作';
                var items = data['Items'] || '无';
                var thoughts = data['Thoughts'] || '无';
                var initial = roleName.charAt(0); // 取首字母做头像

                html += '<div class="trk-card">';

                /* 头部 (默认显示) */
                html += '  <div class="trk-header">';
                html += '    <div class="trk-role-info">';
                html += '      <div class="trk-avatar-icon">' + initial + '</div>';
